#!/usr/bin/env python3
"""Room booking ledger - everything in one file, grown over two years.

    python3 booking.py data/bookings.txt

Complaints the team has filed against this script, none of them chased yet:

  * finance says the occupancy numbers are too high for rooms booked
    back-to-back all morning
  * the 200-to-200 "placeholder" rows are cancellations, but they show up as
    real windows and they even get picked for the projector plan
  * two rooms with identical occupancy pick the "busiest" one by luck
  * the projector plan is worth less than a plan somebody drew by hand on a
    whiteboard, which should not be possible if this thing is optimal
  * peak occupancy is reported one too high whenever a meeting ends exactly
    when the next one starts
  * somebody typed the end time before the start time once and the report
    silently changed instead of complaining
  * the 120k-line archive takes forever
"""
import sys


class Booking(object):
    def __init__(self, room, start, end, weight, tag):
        self.room = room
        self.start = start
        self.end = end
        self.weight = weight
        self.tag = tag

    def __repr__(self):
        return "Booking(%r, %d, %d, %d, %r)" % (
            self.room, self.start, self.end, self.weight, self.tag)


def parse_line(line):
    text = line.strip()
    if not text or text.startswith("#"):
        return None
    parts = text.split("|")
    if len(parts) != 5:
        raise ValueError("bad field count: %s" % text)
    room, start, end, weight, tag = (p.strip() for p in parts)
    s, e = int(start), int(end)
    if e < s:
        s, e = e, s
    return Booking(room, s, e, int(weight), tag)


def load(path):
    out = []
    fh = open(path, encoding="utf-8")
    for line in fh:
        rec = parse_line(line)
        if rec is not None:
            out.append(rec)
    fh.close()
    return out


def merge_windows(intervals):
    windows = [(s, e) for s, e in intervals]
    changed = True
    while changed:
        changed = False
        for i in range(len(windows)):
            for j in range(len(windows)):
                if i == j:
                    continue
                a, b = windows[i], windows[j]
                if a[0] < b[1] and b[0] < a[1]:
                    merged = (min(a[0], b[0]), max(a[1], b[1]))
                    windows = ([w for k, w in enumerate(windows) if k not in (i, j)]
                               + [merged])
                    changed = True
                    break
            if changed:
                break
    return sorted(windows)


def peak(bookings):
    events = []
    for b in bookings:
        events.append((b.start, 0))
        events.append((b.end, 1))
    events.sort()
    cur = best = 0
    at = None
    for time, kind in events:
        cur += 1 if kind == 0 else -1
        if cur > best:
            best, at = cur, time
    return (best, at)


def choose(bookings):
    picked = []
    for b in sorted(bookings, key=lambda x: -x.weight):
        clash = False
        for p in picked:
            if b.start < p.end and p.start < b.end:
                clash = True
                break
        if not clash:
            picked.append(b)
    picked.sort(key=lambda b: (b.start, b.end, b.room, b.tag, b.weight))
    return (sum(b.weight for b in picked), picked)


def summarize(bookings):
    rooms = {}
    for b in bookings:
        rooms.setdefault(b.room, []).append(b)
    summary = {}
    for room, group in rooms.items():
        windows = merge_windows([(b.start, b.end) for b in group])
        summary[room] = {
            "bookings": len(group),
            "windows": windows,
            "minutes": sum(e - s for s, e in windows),
        }
    return summary


def busiest(summary):
    if not summary:
        return None
    return max(summary, key=lambda room: summary[room]["minutes"])


def format_report(bookings):
    summary = summarize(bookings)
    lines = ["rooms=%d" % len(summary)]
    for room in sorted(summary):
        v = summary[room]
        lines.append("room=%s bookings=%d windows=%d minutes=%d"
                     % (room, v["bookings"], len(v["windows"]), v["minutes"]))
        for s, e in v["windows"]:
            lines.append("  [%d,%d)" % (s, e))
    lines.append("total_minutes=%d" % sum(v["minutes"] for v in summary.values()))
    lines.append("busiest=%s" % (busiest(summary) or "-"))
    count, at = peak(bookings)
    lines.append("peak=%d@%s" % (count, "-" if at is None else at))
    weight, chosen = choose(bookings)
    lines.append("plan_weight=%d" % weight)
    lines.append("plan=%s" % ",".join(
        "%s:%d:%d:%s" % (b.room, b.start, b.end, b.tag) for b in chosen))
    return "\n".join(lines) + "\n"


def main(argv):
    if len(argv) != 2:
        sys.stderr.write("usage: python3 booking.py <ledger-file>\n")
        return 2
    try:
        bookings = load(argv[1])
    except ValueError as exc:
        sys.stderr.write("error: %s\n" % exc)
        return 1
    sys.stdout.write(format_report(bookings))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

