"""FROZEN smoke contract for the booking package. Do not edit this file.

It pins the SHAPE of the layout the refactor must produce - names, modules, types - and
almost nothing about behaviour. It is deliberately not an oracle: the rules in the task
description, the report for data/bookings.txt and the report for data/bookings2.txt are
what get graded, and this file will stay green while every one of them is wrong.
"""
import unittest

from booking import (Booking, busiest, choose, load, merge_windows, parse_line,
                     peak, summarize)
from booking.merge import merge_windows as merge_from_module
from booking.model import Booking as Booking_from_module


def B(room, start, end, weight=1, tag="t"):
    return Booking(room=room, start=start, end=end, weight=weight, tag=tag)


class TestMerge(unittest.TestCase):
    def test_single_and_empty(self):
        self.assertEqual(merge_windows([(1, 2)]), [(1, 2)])
        self.assertEqual(merge_windows([]), [])

    def test_reversed_interval_raises(self):
        with self.assertRaises(ValueError) as ctx:
            merge_windows([(30, 10)])
        self.assertIn("end before start: (30, 10)", str(ctx.exception))

    def test_input_is_not_mutated(self):
        data = [(5, 9), (0, 5)]
        merge_windows(data)
        self.assertEqual(data, [(5, 9), (0, 5)])

    def test_same_function_object_as_module(self):
        self.assertIs(merge_windows, merge_from_module,
                      "booking/__init__.py must re-export, not re-implement")


class TestPeak(unittest.TestCase):
    def test_nothing(self):
        self.assertEqual(peak([]), (0, None))
        self.assertEqual(peak([B("A", 5, 5, 9)]), (0, None))



class TestChoose(unittest.TestCase):
    def test_returns_booking_objects_in_ascending_order(self):
        rows = [B("A", 50, 60, 1, "b"), B("A", 0, 10, 1, "a")]
        _weight, chosen = choose(rows)
        self.assertTrue(all(isinstance(b, Booking) for b in chosen))
        self.assertEqual([b.start for b in chosen], [0, 50])

    def test_empty(self):
        self.assertEqual(choose([]), (0, []))

    def test_input_is_not_mutated(self):
        rows = [B("A", 50, 60, 1, "b"), B("A", 0, 10, 1, "a")]
        choose(rows)
        self.assertEqual([b.tag for b in rows], ["b", "a"])


class TestParse(unittest.TestCase):
    def test_comment_and_blank(self):
        self.assertIsNone(parse_line("   \n"))
        self.assertIsNone(parse_line("# a note\n"))

    def test_fields_stripped(self):
        b = parse_line("  Atrium | 10 | 45 | 4 | design \n")
        self.assertEqual((b.room, b.start, b.end, b.weight, b.tag),
                         ("Atrium", 10, 45, 4, "design"))

    def test_reversed_line_raises(self):
        with self.assertRaises(ValueError) as ctx:
            parse_line("Atrium|30|10|1|audit")
        self.assertIn("end before start: Atrium|30|10|1|audit", str(ctx.exception))

    def test_bad_field_count_raises(self):
        with self.assertRaises(ValueError):
            parse_line("Atrium|30|10|audit")


class TestModel(unittest.TestCase):
    def test_booking_is_the_same_class_everywhere(self):
        self.assertIs(Booking, Booking_from_module)

    def test_booking_is_frozen(self):
        b = B("A", 0, 1)
        with self.assertRaises(Exception):
            b.start = 5

    def test_booking_orders_and_compares_by_value(self):
        self.assertEqual(B("A", 0, 1), B("A", 0, 1))
        self.assertLess(B("A", 0, 1), B("A", 0, 2))
        self.assertLess(B("A", 9, 9), B("B", 0, 0))

    def test_booking_is_hashable(self):
        self.assertEqual(len({B("A", 0, 1), B("A", 0, 1)}), 1)


class TestReport(unittest.TestCase):
    def test_busiest_of_nothing_is_none(self):
        self.assertIsNone(busiest(summarize([])))

    def test_load_skips_comments_and_blanks(self):
        self.assertEqual(len(load("data/bookings.txt")), 15)


if __name__ == "__main__":
    unittest.main()
